body.script:
    // Embedded SVG Piece Assets
    const PIECE_SVGS = {"P": "





















", "R": "































", "N": "












































", "B": "







































", "Q": "











































", "K": "












































































", "p": "
























", "r": "











  דבש













", "n": "









































", "b": "
































", "q": "






































", "k": "






  לשנה טובה































































"};

    // Synthesized Sound Effects via Web Audio API
    class RoshHashanahAudio {
      constructor() {
        this.ctx = null;
        this.enabled = true;
      }
      init() {
        if (!this.ctx) {
          this.ctx = new (window.AudioContext || window.webkitAudioContext)();
        }
        if (this.ctx.state === 'suspended') {
          this.ctx.resume();
        }
      }
      playMove() {
        if (!this.enabled) return;
        this.init();
        const now = this.ctx.currentTime;
        const notes = [587.33, 880];
        notes.forEach((freq, i) => {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = 'sine';
          const t = now + i * 0.04;
          osc.frequency.setValueAtTime(freq, t);
          gain.gain.setValueAtTime(0.01, t);
          gain.gain.linearRampToValueAtTime(0.15, t + 0.02);
          gain.gain.exponentialRampToValueAtTime(0.001, t + 0.3);
          osc.connect(gain);
          gain.connect(this.ctx.destination);
          osc.start(t);
          osc.stop(t + 0.3);
        });
      }
      playCapture() {
        if (!this.enabled) return;
        this.init();
        const now = this.ctx.currentTime;
        const osc = this.ctx.createOscillator();
        const gain = this.ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(260, now);
        osc.frequency.exponentialRampToValueAtTime(80, now + 0.18);
        gain.gain.setValueAtTime(0.3, now);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.22);
        osc.connect(gain);
        gain.connect(this.ctx.destination);
        osc.start(now);
        osc.stop(now + 0.22);
      }
      playCheck() {
        if (!this.enabled) return;
        this.init();
        const now = this.ctx.currentTime;
        const osc1 = this.ctx.createOscillator();
        const osc2 = this.ctx.createOscillator();
        const filter = this.ctx.createBiquadFilter();
        const gain = this.ctx.createGain();

        osc1.type = 'sawtooth';
        osc2.type = 'triangle';
        filter.type = 'lowpass';
        filter.frequency.setValueAtTime(1200, now);

        osc1.frequency.setValueAtTime(392, now);
        osc1.frequency.setValueAtTime(392, now + 0.12);
        osc1.frequency.exponentialRampToValueAtTime(523.25, now + 0.16);

        osc2.frequency.setValueAtTime(394, now);
        osc2.frequency.setValueAtTime(394, now + 0.12);
        osc2.frequency.exponentialRampToValueAtTime(525, now + 0.16);

        gain.gain.setValueAtTime(0.01, now);
        gain.gain.linearRampToValueAtTime(0.25, now + 0.05);
        gain.gain.setValueAtTime(0.25, now + 0.38);
        gain.gain.exponentialRampToValueAtTime(0.001, now + 0.55);

        osc1.connect(filter);
        osc2.connect(filter);
        filter.connect(gain);
        gain.connect(this.ctx.destination);

        osc1.start(now);
        osc2.start(now);
        osc1.stop(now + 0.55);
        osc2.stop(now + 0.55);
      }
      playFanfare() {
        if (!this.enabled) return;
        this.init();
        const now = this.ctx.currentTime;
        const notes = [392.00, 523.25, 659.25, 783.99, 1046.50];
        notes.forEach((freq, idx) => {
          const osc = this.ctx.createOscillator();
          const gain = this.ctx.createGain();
          osc.type = idx < 2 ? 'sawtooth' : 'triangle';
          const t = now + idx * 0.15;
          osc.frequency.setValueAtTime(freq, t);
          gain.gain.setValueAtTime(0.02, t);
          gain.gain.linearRampToValueAtTime(0.22, t + 0.04);
          gain.gain.exponentialRampToValueAtTime(0.001, t + 0.5);
          osc.connect(gain);
          gain.connect(this.ctx.destination);
          osc.start(t);
          osc.stop(t + 0.5);
        });
      }
    }


    const COMMENTARY = {
      P: [
        "A crisp Honey Apple rolls forward, spreading sweet blessings!",
        "The sweet apple advances toward the New Year feast.",
        "A golden honey drop paves the path ahead!"
      ],
      R: [
        "The Honey Jar slides into position, anchoring the holiday table with sweetness!",
        "A sturdy Honey Jar rolls into stalwart fortress formation!",
        "Fresh golden honey secures the rank!"
      ],
      N: [
        "The Shofar leaps forward, sounding a joyful fanfare across the ranks!",
        "A spirited leap! The Shofar horn clears the holiday table.",
        "Curving gracefully over the ranks, the Shofar springs into action!"
      ],
      B: [
        "The Kiddush Cup glides gracefully across the table, overflowing with blessings!",
        "A toast to the New Year! The Kiddush Cup sweeps along the diagonal.",
        "Carving a sweet path, the ceremonial Goblet brings holiday joy!"
      ],
      Q: [
        "Queen Malkat Shanah commands the table with 613 blessings!",
        "The Queen sweeps across the board, spreading sweetness and light.",
        "Radiating royal dignity, the Queen takes center stage!"
      ],
      K: [
        "The Imperial King Crown shines with royal majesty upon the Book of Life.",
        "Keter Melech stands firm at the head of the year.",
        "The Sovereign Crown watches over the New Year gathering with solemn grace."
      ],
      capture: [
        "🍎 DIPPED! A sweet crunch claims the square!",
        "🍯 Dipped in honey! Piece whisked away from the feast!",
        "🍷 A burst of ruby pomegranate sweetness claims the tile!",
        "✨ Cleared from the table to make room for sweet blessings!"
      ],
      check: [
        "🎺 TEKIAH! The Shofar sounds an urgent wake-up call to the King!",
        "🎺 TERUAH! Rapid horn blasts alert the royal court!",
        "⚠️ High Alert! The King must take heed of the Shofar call!"
      ]
    };

    class RoshHashanahChess {
      constructor() {
        this.reset();
      }
      reset() {
        this.board = [
          ['r', 'n', 'b', 'q', 'k', 'b', 'n', 'r'],
          ['p', 'p', 'p', 'p', 'p', 'p', 'p', 'p'],
          [null, null, null, null, null, null, null, null],
          [null, null, null, null, null, null, null, null],
          [null, null, null, null, null, null, null, null],
          [null, null, null, null, null, null, null, null],
          ['P', 'P', 'P', 'P', 'P', 'P', 'P', 'P'],
          ['R', 'N', 'B', 'Q', 'K', 'B', 'N', 'R']
        ];
        this.turn = 'w';
        this.castling = { K: true, Q: true, k: true, q: true };
        this.enPassant = null;
        this.history = [];
        this.capturedWhite = [];
        this.capturedBlack = [];
      }
      cloneBoard(b) {
        return b.map(r => [...r]);
      }
      isWhite(p) { return p && p === p.toUpperCase(); }
      isBlack(p) { return p && p === p.toLowerCase(); }
      getColor(p) { if (!p) return null; return this.isWhite(p) ? 'w' : 'b'; }
      inBounds(r, c) { return r >= 0 && r < 8 && c >= 0 && c < 8; }
      findKing(board, color) {
        const target = color === 'w' ? 'K' : 'k';
        for (let r = 0; r < 8; r++) {
          for (let c = 0; c < 8; c++) {
            if (board[r][c] === target) return { r, c };
          }
        }
        return null;
      }
      isSquareAttacked(r, c, color, board = this.board) {
        const oppColor = color === 'w' ? 'b' : 'w';
        const pawnP = oppColor === 'w' ? 'P' : 'p';
        const pawnStep = color === 'w' ? -1 : 1;
        for (let dc of [-1, 1]) {
          const pr = r + pawnStep, pc = c + dc;
          if (this.inBounds(pr, pc) && board[pr][pc] === pawnP) return true;
        }
        const knightP = oppColor === 'w' ? 'N' : 'n';
        const knightOffsets = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];
        for (let [dr, dc] of knightOffsets) {
          const nr = r + dr, nc = c + dc;
          if (this.inBounds(nr, nc) && board[nr][nc] === knightP) return true;
        }
        const kingP = oppColor === 'w' ? 'K' : 'k';
        for (let dr = -1; dr <= 1; dr++) {
          for (let dc = -1; dc <= 1; dc++) {
            if (dr === 0 && dc === 0) continue;
            const kr = r + dr, kc = c + dc;
            if (this.inBounds(kr, kc) && board[kr][kc] === kingP) return true;
          }
        }
        const rookP = oppColor === 'w' ? 'R' : 'r';
        const queenP = oppColor === 'w' ? 'Q' : 'q';
        for (let [dr, dc] of [[-1, 0], [1, 0], [0, -1], [0, 1]]) {
          let cr = r + dr, cc = c + dc;
          while (this.inBounds(cr, cc)) {
            const p = board[cr][cc];
            if (p) {
              if (p === rookP || p === queenP) return true;
              break;
            }
            cr += dr; cc += dc;
          }
        }
        const bishopP = oppColor === 'w' ? 'B' : 'b';
        for (let [dr, dc] of [[-1, -1], [-1, 1], [1, -1], [1, 1]]) {
          let cr = r + dr, cc = c + dc;
          while (this.inBounds(cr, cc)) {
            const p = board[cr][cc];
            if (p) {
              if (p === bishopP || p === queenP) return true;
              break;
            }
            cr += dr; cc += dc;
          }
        }
        return false;
      }
      isCheck(color = this.turn, board = this.board) {
        const kPos = this.findKing(board, color);
        if (!kPos) return false;
        return this.isSquareAttacked(kPos.r, kPos.c, color, board);
      }
      getPseudoLegalMoves(r, c) {
        const p = this.board[r][c];
        if (!p) return [];
        const color = this.getColor(p);
        if (color !== this.turn) return [];
        const moves = [];
        const pType = p.toUpperCase();

        if (pType === 'P') {
          const dir = color === 'w' ? -1 : 1;
          const startRank = color === 'w' ? 6 : 1;
          const promoRank = color === 'w' ? 0 : 7;
          if (this.inBounds(r + dir, c) && !this.board[r + dir][c]) {
            moves.push({ from: { r, c }, to: { r: r + dir, c }, isPromo: (r + dir) === promoRank });
            if (r === startRank && !this.board[r + 2 * dir][c]) {
              moves.push({ from: { r, c }, to: { r: r + 2 * dir, c }, isDoublePawn: true });
            }
          }
          for (let dc of [-1, 1]) {
            const tr = r + dir, tc = c + dc;
            if (this.inBounds(tr, tc)) {
              const target = this.board[tr][tc];
              if (target && this.getColor(target) !== color) {
                moves.push({ from: { r, c }, to: { r: tr, c: tc }, isPromo: tr === promoRank, isCapture: true });
              } else if (this.enPassant && this.enPassant.r === tr && this.enPassant.c === tc) {
                moves.push({ from: { r, c }, to: { r: tr, c: tc }, isEnPassant: true, isCapture: true });
              }
            }
          }
        } else if (pType === 'N') {
          const knightOffsets = [[-2, -1], [-2, 1], [-1, -2], [-1, 2], [1, -2], [1, 2], [2, -1], [2, 1]];
          for (let [dr, dc] of knightOffsets) {
            const tr = r + dr, tc = c + dc;
            if (this.inBounds(tr, tc)) {
              const target = this.board[tr][tc];
              if (!target || this.getColor(target) !== color) {
                moves.push({ from: { r, c }, to: { r: tr, c: tc }, isCapture: !!target });
              }
            }
          }
        } else if (pType === 'B' || pType === 'R' || pType === 'Q') {
          const dirs = [];
          if (pType === 'B' || pType === 'Q') dirs.push([-1, -1], [-1, 1], [1, -1], [1, 1]);
          if (pType === 'R' || pType === 'Q') dirs.push([-1, 0], [1, 0], [0, -1], [0, 1]);
          for (let [dr, dc] of dirs) {
            let tr = r + dr, tc = c + dc;
            while (this.inBounds(tr, tc)) {
              const target = this.board[tr][tc];
              if (!target) {
                moves.push({ from: { r, c }, to: { r: tr, c: tc } });
              } else {
                if (this.getColor(target) !== color) {
                  moves.push({ from: { r, c }, to: { r: tr, c: tc }, isCapture: true });
                }
                break;
              }
              tr += dr; tc += dc;
            }
          }
        } else if (pType === 'K') {
          for (let dr = -1; dr <= 1; dr++) {
            for (let dc = -1; dc <= 1; dc++) {
              if (dr === 0 && dc === 0) continue;
              const tr = r + dr, tc = c + dc;
              if (this.inBounds(tr, tc)) {
                const target = this.board[tr][tc];
                if (!target || this.getColor(target) !== color) {
                  moves.push({ from: { r, c }, to: { r: tr, c: tc }, isCapture: !!target });
                }
              }
            }
          }
          if (!this.isCheck(color)) {
            if (color === 'w' && r === 7 && c === 4) {
              if (this.castling.K && !this.board[7][5] && !this.board[7][6] && this.board[7][7] === 'R') {
                if (!this.isSquareAttacked(7, 5, 'w') && !this.isSquareAttacked(7, 6, 'w')) {
                  moves.push({ from: { r, c }, to: { r: 7, c: 6 }, isCastle: 'K' });
                }
              }
              if (this.castling.Q && !this.board[7][3] && !this.board[7][2] && !this.board[7][1] && this.board[7][0] === 'R') {
                if (!this.isSquareAttacked(7, 3, 'w') && !this.isSquareAttacked(7, 2, 'w')) {
                  moves.push({ from: { r, c }, to: { r: 7, c: 2 }, isCastle: 'Q' });
                }
              }
            } else if (color === 'b' && r === 0 && c === 4) {
              if (this.castling.k && !this.board[0][5] && !this.board[0][6] && this.board[0][7] === 'r') {
                if (!this.isSquareAttacked(0, 5, 'b') && !this.isSquareAttacked(0, 6, 'b')) {
                  moves.push({ from: { r, c }, to: { r: 0, c: 6 }, isCastle: 'k' });
                }
              }
              if (this.castling.q && !this.board[0][3] && !this.board[0][2] && !this.board[0][1] && this.board[0][0] === 'r') {
                if (!this.isSquareAttacked(0, 3, 'b') && !this.isSquareAttacked(0, 2, 'b')) {
                  moves.push({ from: { r, c }, to: { r: 0, c: 2 }, isCastle: 'q' });
                }
              }
            }
          }
        }
        return moves;
      }
      getLegalMoves(r, c) {
        const pseudo = this.getPseudoLegalMoves(r, c);
        return pseudo.filter(m => {
          const nextBoard = this.cloneBoard(this.board);
          const piece = nextBoard[m.from.r][m.from.c];
          nextBoard[m.to.r][m.to.c] = piece;
          nextBoard[m.from.r][m.from.c] = null;
          if (m.isEnPassant) {
            const epRow = piece === 'P' ? m.to.r + 1 : m.to.r - 1;
            nextBoard[epRow][m.to.c] = null;
          }
          const color = this.getColor(piece);
          return !this.isCheck(color, nextBoard);
        });
      }
      getAllLegalMoves() {
        const all = [];
        for (let r = 0; r < 8; r++) {
          for (let c = 0; c < 8; c++) {
            if (this.board[r][c] && this.getColor(this.board[r][c]) === this.turn) {
              all.push(...this.getLegalMoves(r, c));
            }
          }
        }
        return all;
      }
      makeMove(move, promotionChoice = 'Q') {
        const { from, to, isCastle, isEnPassant, isDoublePawn, isPromo } = move;
        const piece = this.board[from.r][from.c];
        const color = this.getColor(piece);
        let captured = this.board[to.r][to.c];

        this.history.push({
          board: this.cloneBoard(this.board),
          turn: this.turn,
          castling: { ...this.castling },
          enPassant: this.enPassant ? { ...this.enPassant } : null,
          capturedWhite: [...this.capturedWhite],
          capturedBlack: [...this.capturedBlack],
          move: { ...move, piece, captured, promotionChoice }
        });

        this.board[to.r][to.c] = piece;
        this.board[from.r][from.c] = null;

        if (isEnPassant) {
          const epRow = color === 'w' ? to.r + 1 : to.r - 1;
          captured = this.board[epRow][to.c];
          this.board[epRow][to.c] = null;
        }

        if (captured) {
          if (this.isWhite(captured)) this.capturedWhite.push(captured);
          else this.capturedBlack.push(captured);
        }

        if (isCastle) {
          if (isCastle === 'K') { this.board[7][5] = 'R'; this.board[7][7] = null; }
          else if (isCastle === 'Q') { this.board[7][3] = 'R'; this.board[7][0] = null; }
          else if (isCastle === 'k') { this.board[0][5] = 'r'; this.board[0][7] = null; }
          else if (isCastle === 'q') { this.board[0][3] = 'r'; this.board[0][0] = null; }
        }

        if (isPromo) {
          const promoPiece = color === 'w' ? promotionChoice.toUpperCase() : promotionChoice.toLowerCase();
          this.board[to.r][to.c] = promoPiece;
        }

        if (piece === 'K') { this.castling.K = false; this.castling.Q = false; }
        if (piece === 'k') { this.castling.k = false; this.castling.q = false; }
        if (from.r === 7 && from.c === 7) this.castling.K = false;
        if (from.r === 7 && from.c === 0) this.castling.Q = false;
        if (from.r === 0 && from.c === 7) this.castling.k = false;
        if (from.r === 0 && from.c === 0) this.castling.q = false;
        if (to.r === 7 && to.c === 7) this.castling.K = false;
        if (to.r === 7 && to.c === 0) this.castling.Q = false;
        if (to.r === 0 && to.c === 7) this.castling.k = false;
        if (to.r === 0 && to.c === 0) this.castling.q = false;

        if (isDoublePawn) {
          const epRow = color === 'w' ? from.r - 1 : from.r + 1;
          this.enPassant = { r: epRow, c: from.c };
        } else {
          this.enPassant = null;
        }

        this.turn = this.turn === 'w' ? 'b' : 'w';

        const oppMoves = this.getAllLegalMoves();
        const inCheck = this.isCheck(this.turn);
        let status = 'active';
        if (oppMoves.length === 0) {
          status = inCheck ? 'checkmate' : 'stalemate';
        }

        return { status, inCheck, captured, piece };
      }
      undo() {
        if (this.history.length === 0) return null;
        const last = this.history.pop();
        this.board = last.board;
        this.turn = last.turn;
        this.castling = last.castling;
        this.enPassant = last.enPassant;
        this.capturedWhite = last.capturedWhite;
        this.capturedBlack = last.capturedBlack;
        return last;
      }
    }

    // Controller & UI Binding
    const game = new RoshHashanahChess();
    const audio = new RoshHashanahAudio();
    let selectedSquare = null;
    let validMoves = [];
    let isFlipped = false;
    let pendingPromoMove = null;

    const boardEl = document.getElementById('chessBoard');
    const boardContainer = document.getElementById('boardContainer');
    const turnIndicator = document.getElementById('turnIndicator');
    const turnAvatar = document.getElementById('turnAvatar');
    const turnText = document.getElementById('turnText');
    const checkBadge = document.getElementById('checkBadge');
    const commentaryBanner = document.getElementById('commentaryBanner');
    const whiteCapturedTray = document.getElementById('whiteCapturedTray');
    const blackCapturedTray = document.getElementById('blackCapturedTray');
    const chkAutoRotate = document.getElementById('chkAutoRotate');
    const promoModal = document.getElementById('promoModal');
    const promoGrid = document.getElementById('promoGrid');
    const gameOverModal = document.getElementById('gameOverModal');
    const gameOverTitle = document.getElementById('gameOverTitle');
    const gameOverMsg = document.getElementById('gameOverMsg');

    function renderBoard() {
      boardEl.innerHTML = '';
      const inCheck = game.isCheck(game.turn);
      const kPos = inCheck ? game.findKing(game.board, game.turn) : null;

      for (let r = 0; r < 8; r++) {
        for (let c = 0; c < 8; c++) {
          const sq = document.createElement('div');
          const isLight = (r + c) % 2 === 0;
          sq.className = `square ${isLight ? 'light' : 'dark'}`;
          sq.dataset.r = r;
          sq.dataset.c = c;

          // Check coordinate labels
          if (c === 0) {
            const rankLabel = document.createElement('span');
            rankLabel.className = 'coord coord-rank';
            rankLabel.innerText = 8 - r;
            sq.appendChild(rankLabel);
          }
          if (r === 7) {
            const fileLabel = document.createElement('span');
            fileLabel.className = 'coord coord-file';
            fileLabel.innerText = String.fromCharCode(97 + c);
            sq.appendChild(fileLabel);
          }

          // Selected highlight
          if (selectedSquare && selectedSquare.r === r && selectedSquare.c === c) {
            sq.classList.add('selected');
          }

          // King in check red highlight
          if (kPos && kPos.r === r && kPos.c === c) {
            sq.classList.add('in-check');
          }

          // Piece
          const p = game.board[r][c];
          if (p && PIECE_SVGS[p]) {
            const wrapper = document.createElement('div');
            wrapper.className = 'rh-piece-wrapper';
            wrapper.innerHTML = PIECE_SVGS[p];
            sq.appendChild(wrapper);
          }

          // Move hint
          const moveMatch = validMoves.find(m => m.to.r === r && m.to.c === c);
          if (moveMatch) {
            const hint = document.createElement('div');
            hint.className = moveMatch.isCapture ? 'capture-hint' : 'move-hint';
            sq.appendChild(hint);
          }

          sq.addEventListener('click', () => onSquareClick(r, c));
          boardEl.appendChild(sq);
        }
      }

      updateStatusUI();
    }

    function onSquareClick(r, c) {
      const p = game.board[r][c];
      const pColor = game.getColor(p);

      // If clicked on own piece: select it
      if (p && pColor === game.turn) {
        selectedSquare = { r, c };
        validMoves = game.getLegalMoves(r, c);
        renderBoard();
        return;
      }

      // If a piece is already selected, check if clicked square is a valid target
      if (selectedSquare) {
        const targetMove = validMoves.find(m => m.to.r === r && m.to.c === c);
        if (targetMove) {
          if (targetMove.isPromo) {
            pendingPromoMove = targetMove;
            openPromoModal();
          } else {
            executeMove(targetMove);
          }
          return;
        }
      }

      // Otherwise deselect
      selectedSquare = null;
      validMoves = [];
      renderBoard();
    }

    function executeMove(move, promoChoice = 'Q') {
      const res = game.makeMove(move, promoChoice);
      selectedSquare = null;
      validMoves = [];

      // Audio feedback
      if (res.status === 'checkmate') {
        audio.playFanfare();
      } else if (res.inCheck) {
        audio.playCheck();
      } else if (res.captured) {
        audio.playCapture();
      } else {
        audio.playMove();
      }

      // Commentary flavor
      const pType = (move.isPromo ? promoChoice : res.piece).toUpperCase();
      let comment = '';
      if (res.status === 'checkmate') {
        comment = `🏆 Checkmate! The ${game.turn === 'w' ? 'Midnight Zoomies' : 'Sunny Slackers'} triumph! Inscribed for a sweet New Year!`;
      } else if (res.inCheck) {
        comment = COMMENTARY.check[Math.floor(Math.random() * COMMENTARY.check.length)];
      } else if (res.captured) {
        comment = COMMENTARY.capture[Math.floor(Math.random() * COMMENTARY.capture.length)];
      } else if (COMMENTARY[pType]) {
        const arr = COMMENTARY[pType];
        comment = arr[Math.floor(Math.random() * arr.length)];
      }
      commentaryBanner.innerText = comment;

      // Auto-rotate if enabled
      if (chkAutoRotate.checked) {
        isFlipped = (game.turn === 'b');
        boardContainer.classList.toggle('flipped', isFlipped);
      }

      renderBoard();

      if (res.status === 'checkmate') {
        const winner = game.turn === 'w' ? 'Ruby Pomegranates (Black)' : 'Golden Honey (White)';
        gameOverTitle.innerText = '🏆 Shanah Tovah U'Metukah!';
        gameOverMsg.innerText = `${winner} win the holiday feast! May your year be sweet as honey and filled with blessings as a pomegranate has seeds!`;
        gameOverModal.style.display = 'flex';
      } else if (res.status === 'stalemate') {
        gameOverTitle.innerText = '🕊️ Shalom! Stalemate!';
        gameOverMsg.innerText = 'Neither side has a legal move! Both sides share apples and honey in peaceful harmony.';
        gameOverModal.style.display = 'flex';
      }
    }

    function openPromoModal() {
      promoGrid.innerHTML = '';
      const color = game.turn;
      const options = color === 'w' ? [
        { key: 'Q', title: 'Queen Malkat Shanah' },
        { key: 'R', title: 'Glass Honey Jar (Rook)' },
        { key: 'N', title: 'Sculpted Shofar (Knight)' },
        { key: 'B', title: 'Silver Kiddush Cup (Bishop)' }
      ] : [
        { key: 'q', title: 'Pomegranate Empress (Queen)' },
        { key: 'r', title: 'Heritage Honey Crock (Rook)' },
        { key: 'n', title: 'Yemenite Kudu Shofar (Knight)' },
        { key: 'b', title: 'Royal Kiddush Chalice (Bishop)' }
      ];

      options.forEach(opt => {
        const optKey = opt.key;
        const card = document.createElement('div');
        card.className = 'promo-option';
        card.innerHTML = `

${PIECE_SVGS[optKey]}

${opt.title}
        `;
        card.addEventListener('click', () => {
          promoModal.style.display = 'none';
          if (pendingPromoMove) {
            const move = pendingPromoMove;
            pendingPromoMove = null;
            executeMove(move, opt.key.toUpperCase());
          }
        });
        promoGrid.appendChild(card);
      });

      promoModal.style.display = 'flex';
    }

    function updateStatusUI() {
      const isWhiteTurn = game.turn === 'w';
      turnText.innerText = isWhiteTurn ? "Golden Honey's Turn 🍯 🐾" : "Midnight Zoomies' Turn 🐾";
      turnAvatar.className = `player-avatar ${isWhiteTurn ? '' : 'black-team'}`;
      turnAvatar.innerHTML = isWhiteTurn ? PIECE_SVGS['K'] : PIECE_SVGS['k'];

      const inCheck = game.isCheck(game.turn);
      checkBadge.style.display = inCheck ? 'inline-block' : 'none';

      // Update captured trays
      whiteCapturedTray.innerHTML = game.capturedWhite.map(p => `
${PIECE_SVGS[p]}`).join('');
      blackCapturedTray.innerHTML = game.capturedBlack.map(p => `
${PIECE_SVGS[p]}`).join('');
    }

    // Event Listeners
    document.getElementById('btnFlip').addEventListener('click', () => {
      isFlipped = !isFlipped;
      boardContainer.classList.toggle('flipped', isFlipped);
    });

    document.getElementById('btnUndo').addEventListener('click', () => {
      const undone = game.undo();
      if (undone) {
        selectedSquare = null;
        validMoves = [];
        commentaryBanner.innerText = '↩️ Move undone! Re-evaluating the table position.';
        if (chkAutoRotate.checked) {
          isFlipped = (game.turn === 'b');
          boardContainer.classList.toggle('flipped', isFlipped);
        }
        renderBoard();
      }
    });

    document.getElementById('btnNewGame').addEventListener('click', () => {
      if (confirm('Start a fresh Rosh Hashanah chess match?')) {
        game.reset();
        selectedSquare = null;
        validMoves = [];
        isFlipped = false;
        boardContainer.classList.remove('flipped');
        commentaryBanner.innerText = '🍯 Fresh match started! Golden Honey (White) to move.';
        gameOverModal.style.display = 'none';
        renderBoard();
      }
    });

    document.getElementById('btnPlayAgain').addEventListener('click', () => {
      game.reset();
      selectedSquare = null;
      validMoves = [];
      isFlipped = false;
      boardContainer.classList.remove('flipped');
      commentaryBanner.innerText = '🍯 Fresh match started! Golden Honey (White) to move.';
      gameOverModal.style.display = 'none';
      renderBoard();
    });

    const btnSound = document.getElementById('btnSound');
    btnSound.addEventListener('click', () => {
      audio.enabled = !audio.enabled;
      btnSound.innerText = audio.enabled ? '🔊 Sound' : '🔇 Muted';
    });

    // Initial render
    renderBoard();
